// Package docs serves the API specification and an interactive Swagger UI.
//
// The spec is hand-authored (openapi.yaml) rather than generated by swag from
// struct-tag annotations. The handlers still carry swaggo-style `@Summary` /
// `@Param` comments as documentation for a human reading the source, and
// running `swag init` against them would produce a spec that supersedes this
// one — but generating it requires network access this build environment does
// not have, and a hand-written spec that ships today beats a generated one
// that doesn't. Swapping to generated docs later is a build-step change, not
// an API change: the route this package registers stays /swagger/index.html
// either way.
package docs

import (
	"embed"
	"net/http"

	"github.com/gin-gonic/gin"
)

//go:embed openapi.yaml
var openAPISpec embed.FS

// swaggerUIHTML loads swagger-ui-dist from a CDN and points it at our own
// embedded spec. Pulling the UI assets from a CDN rather than vendoring them
// keeps this package to two files; the spec itself, the thing actually worth
// version-controlling, stays local and offline-readable.
const swaggerUIHTML = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Myntra Bharat AI — API Docs</title>
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/5.17.14/swagger-ui.min.css">
  <style>body { margin: 0; }</style>
</head>
<body>
  <div id="swagger-ui"></div>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/5.17.14/swagger-ui-bundle.min.js"></script>
  <script>
    window.onload = () => {
      window.ui = SwaggerUIBundle({
        url: "/docs/openapi.yaml",
        dom_id: "#swagger-ui",
        presets: [SwaggerUIBundle.presets.apis, SwaggerUIBundle.SwaggerUIStandalonePreset],
        layout: "BaseLayout",
      });
    };
  </script>
</body>
</html>`

// Register mounts the spec and the UI.
//
//	GET /docs/openapi.yaml   — the raw spec, also fetchable directly for
//	                           import into Postman or another client.
//	GET /swagger/index.html  — the interactive UI, per the brief.
func Register(router *gin.Engine) {
	router.GET("/docs/openapi.yaml", func(c *gin.Context) {
		spec, err := openAPISpec.ReadFile("openapi.yaml")
		if err != nil {
			c.Status(http.StatusInternalServerError)
			return
		}
		c.Data(http.StatusOK, "application/yaml", spec)
	})

	router.GET("/swagger/index.html", func(c *gin.Context) {
		c.Data(http.StatusOK, "text/html; charset=utf-8", []byte(swaggerUIHTML))
	})
	// A bare /swagger redirects to the canonical path so either one works from
	// muscle memory.
	router.GET("/swagger", func(c *gin.Context) {
		c.Redirect(http.StatusMovedPermanently, "/swagger/index.html")
	})
}
